    or "923001234567". Spaces and dashes are ignored. Raise ValueError if the
    result isn't a valid mobile number (+92, then 3, then nine more digits).
    """
    if not isinstance(number, str):
        raise ValueError("not a valid mobile number")

    s = number.strip()
    if not s:
        raise ValueError("not a valid mobile number")

    if s.startswith("0"):
        # Local format: drop dashes; keep a single space after "+92" if the
        # original input contained spaces.
        t = s.replace("-", "")
        if " " in t:
            out = "+92 " + t[1:].replace("  ", " ")
        else:
            out = "+92" + t[1:]
    elif s.startswith("+") or s.startswith("92"):
        # International format: ignore spaces and dashes.
        out = "+" + re.sub(r"[\s-]", "", s.lstrip("+"))
    else:
        raise ValueError("not a valid mobile number")

    # Final validation: +92, then 3, then nine more digits.
    compact = re.sub(r"[\s-]", "", out)
    if not re.fullmatch(r"\+923\d{9}", compact):
        raise ValueError("not a valid mobile number")

    return out

