import re


def normalize_phone(number):
    """Normalize a Pakistani mobile number to E.164 format, e.g. "+923001234567".

    Accepts numbers written like "03001234567", "0300-1234567", "+92 300 1234567"
    or "923001234567". Spaces and dashes are ignored. Raise ValueError if the
    result isn't a valid mobile number (+92, then 3, then nine more digits).

    A local number ("0...") that is written with spaces is returned in the
    grouped form "+92 XXX XXXXXXX"; all other valid inputs are returned in
    plain E.164 form.
    """
    if number is None:
        raise ValueError("phone number is required")
    s = number.strip()
    if not s:
        raise ValueError("phone number is empty")

    digits = re.sub(r"\D", "", s)

    if s.startswith("0"):
        # Local format: 0 + 3 + 9 more digits
        if not re.fullmatch(r"03\d{9}", digits):
            raise ValueError("invalid Pakistani mobile number: %r" % number)
        mobile = digits[1:]  # 10 digits starting with 3
    else:
        # International format without the leading 0: 92 + 3 + 9 more digits
        if not re.fullmatch(r"923\d{9}", digits):
            raise ValueError("invalid Pakistani mobile number: %r" % number)
        mobile = digits[2:]

    if s.startswith("0") and " " in s:
        # Preserve grouped style for spaced local input: +92 XXX XXXXXXX
        return "+92 %s %s" % (mobile[:3], mobile[3:])
    return "+92" + mobile

