def cart_total(items, code=None):
    """Return the total price of a cart, rounded to 2 decimal places.

    items is a list of (price, quantity) pairs. The discount code "SAVE10"
    takes 10% off the whole cart. Any other code raises ValueError.
    """
    total = sum(price * qty for price, qty in items)
    if code is not None:
        if code == "SAVE10":
            total *= 0.9
        else:
            raise ValueError(f"Unknown discount code: {code}")
    return round(total, 2)

def cart_total(items, code=None):
    """Return the total price of a cart, rounded to 2 decimal places.

    items is a list of (price, quantity) pairs. The discount code "SAVE10"
    takes 10% off the whole cart (15% off for carts over $1000).
    Any other code raises ValueError.
    """
    total = sum(price * qty for price, qty in items)
    if code is not None:
        if code == "SAVE10":
            rate = 0.15 if total > 1000 else 0.10
            total *= 1 - rate
        else:
            raise ValueError(f"Unknown discount code: {code}")
    return round(total, 2)

