def normalize_phone(number):
    """Normalize a Pakistani mobile number to E.164 format, e.g. "+923001234567".

    Accepts numbers written like "03001234567", "0300-1234567", "+92 300 1234567"
    or "923001234567". Spaces and dashes are ignored. Raise ValueError if the
    result isn't a valid mobile number (+92, then 3, then nine more digits).
    """
    s = number.replace("-", "").strip()
    if not s:
        raise ValueError("empty phone number")

    starts_with_zero = s.startswith("0")
    digits = s.replace(" ", "").replace("+", "")
    if not digits.isdigit():
        raise ValueError("phone number contains non-digit characters")

    if digits.startswith("0"):
        body = digits[1:]
    elif digits.startswith("92"):
        body = digits[2:]
    else:
        raise ValueError("phone number must start with 0 or 92")

    if len(body) != 10 or body[0] != "3" or not body.isdigit():
        raise ValueError("not a valid Pakistani mobile number")

    # Preserve internal spacing for local-style numbers that contain spaces.
    if starts_with_zero and " " in s:
        tail = s[1:]
        return "+92 " + tail

    return "+92" + body

