            raise ValueError(f"Invalid phone number: {number!r}")
        if digits[1:3] != "92":
            raise ValueError(f"Invalid country code: {number!r}")
        rest = digits[3:]
    else:
        if not digits.isdigit():
            raise ValueError(f"Invalid phone number: {number!r}")
        if digits.startswith("0") and digits[1] == "3":
            # Local format: 03XX-XXXXXXX
            rest = digits[1:]
        elif digits.startswith("92"):
            # International without plus
            rest = digits[2:]
        else:
            raise ValueError(f"Invalid phone number: {number!r}")

    if len(rest) == 10 and rest[0] == "3" and rest.isdigit():
        return "+92" + rest

    raise ValueError(f"Not a valid Pakistani mobile number: {number!r}")

