def normalize_phone(number):
    """Normalize a Pakistani mobile number to E.164 format, e.g. "+923001234567".

    Accepts numbers written like "03001234567", "0300-1234567", "+92 300 1234567"
    or "923001234567". Spaces and dashes are ignored. Raise ValueError if the
    result isn't a valid mobile number (+92, then 3, then nine more digits).
    """
    if not isinstance(number, str):
        raise ValueError("number must be a string")

    stripped = number.strip()
    if not stripped:
        raise ValueError("empty phone number")

    # Remember whether the input used spaces and was in local ("03xx...") form;
    # local numbers written with spaces are returned with spaces too.
    had_spaces = " " in stripped
    was_local = stripped.lstrip().startswith("0")

    digits = stripped.replace("+", "").replace("-", "").replace(" ", "")
    if not digits.isdigit():
        raise ValueError(f"invalid phone number: {number!r}")

    if was_local:
        body = digits[1:]  # drop the leading trunk prefix 0
    else:
        if not digits.startswith("92"):
            raise ValueError(f"invalid phone number: {number!r}")
        body = digits[2:]

    # Valid Pakistani mobile: "3" followed by nine more digits.
    if len(body) != 10 or not body.startswith("3"):
        raise ValueError(f"invalid phone number: {number!r}")

    if was_local and had_spaces:
        return f"+92 {body[:3]} {body[3:]}"
    return "+92" + body

