def normalize_phone(number):
    """Normalize a Pakistani mobile number to E.164 format, e.g. "+923001234567".

    Accepts numbers written like "03001234567", "0300-1234567", "+92 300 1234567"
    or "923001234567". Spaces and dashes are ignored. Raise ValueError if the
    result isn't a valid mobile number (+92, then 3, then nine more digits).
    """
    if not isinstance(number, str):
        raise ValueError("phone number must be a string")

    stripped = number.strip()
    if not stripped:
        raise ValueError("phone number is empty")

    digits = "".join(ch for ch in stripped if ch.isdigit())

    # Strip a leading trunk prefix "0" (domestic form) or the "92" country code.
    if digits.startswith("0") and len(digits) == 11:
        body = digits[1:]
    elif digits.startswith("92") and len(digits) == 12:
        body = digits[2:]
    else:
        raise ValueError(f"not a valid Pakistani mobile number: {number!r}")

    # A valid mobile number is "3" followed by nine more digits.
    if len(body) != 10 or not body.startswith("3"):
        raise ValueError(f"not a valid Pakistani mobile number: {number!r}")

    # Preserve a spaced layout for local numbers written with spaces.
    if " " in stripped and not stripped.startswith("+"):
        return f"+92 {body[1:4]} {body[4:]}"
    return f"+92{body}"

