def cart_total(items, code=None):
    """Return the total price of a cart, rounded to 2 decimal places.

    items is a list of (price, quantity) pairs. The discount code "SAVE10"
    takes 10% off the whole cart (15% off when the cart total exceeds
    1500). Any other code raises ValueError.
    """
    total = round(sum(price * qty for price, qty in items), 2)
    if code is not None:
        if code == "SAVE10":
            if total > 1500:
                total = round(total * 0.85, 2)
            else:
                total = round(total * 0.90, 2)
        else:
            raise ValueError(f"Unknown discount code: {code}")
    return total

