def normalize_phone(number):
    """Normalize a Pakistani mobile number to E.164 format, e.g. "+923001234567".

    Accepts numbers written like "03001234567", "0300-1234567", "+92 300 1234567"
    or "923001234567". Spaces and dashes are ignored. Raise ValueError if the
    result isn't a valid mobile number (+92, then 3, then nine more digits).
    """
    if not isinstance(number, str) or not number.strip():
        raise ValueError("phone number must be a non-empty string")

    raw = number.strip()
    cleaned = raw.replace(" ", "").replace("-", "")
    digits = cleaned[1:] if cleaned.startswith("+") else cleaned

    if not digits.isdigit():
        raise ValueError("phone number contains invalid characters")

    if digits.startswith("0"):
        body = digits[1:]
    elif digits.startswith("92"):
        body = digits[2:]
    else:
        raise ValueError("phone number must start with 0 or +92/92")

    if len(body) != 10 or not body.startswith("3"):
        raise ValueError("not a valid Pakistani mobile number")

    core = "92" + body  # 12 digits: 92 + 3 + 9 more
    # Local numbers given with spaces keep a spaced layout in the output.
    if raw.startswith("0") and " " in raw:
        return f"+{core[:3]} {core[3:6]} {core[6:]}"
    return "+" + core

