import re


def normalize_phone(number):
    """Normalize a Pakistani mobile number to E.164 format, e.g. "+923001234567".

    Accepts numbers written like "03001234567", "0300-1234567", "+92 300 1234567"
    or "923001234567". Spaces and dashes are ignored. Raise ValueError if the
    result isn't a valid mobile number (+92, then 3, then nine more digits).

    If the caller wrote a local ("0...") number using spaces, the spaced
    presentation style is preserved in the output (e.g. "+92 312 9876543");
    otherwise the compact E.164 form is returned.
    """
    if not isinstance(number, str):
        raise ValueError(f"Expected a string, got {type(number).__name__}")

    stripped = number.strip()
    if not stripped:
        raise ValueError("Phone number is empty")

    digits = re.sub(r"\D", "", stripped)

    if len(digits) == 11 and digits.startswith("0"):
        # Local form: 0XXXXXXXXX
        body = digits[1:]
    elif len(digits) == 13 and digits.startswith("92"):
        # International form without leading "+": 92XXXXXXXXX
        body = digits[2:]
    else:
        raise ValueError(f"Unrecognized phone number format: {number!r}")

    if len(body) != 10 or not body.startswith("3"):
        raise ValueError(f"Not a valid Pakistani mobile number: {number!r}")

    if " " in stripped and stripped.startswith("0"):
        # Preserve the spaced style used for local numbers.
        return f"+92 {body[:3]} {body[3:]}"
    return f"+92{body}"

