def cart_total(items, code=None):
    """Return the total price of a cart, rounded to 2 decimal places.

    items is a list of (price, quantity) pairs. The discount code "SAVE10"
    takes 10% off the whole cart, plus an extra 5% off when the pre-discount
    total is $1000 or more. Any other code raises ValueError.
    """
    total = sum(price * qty for price, qty in items)
    if code is not None:
        if code == "SAVE10":
