def normalize_phone(number):
    """Normalize a Pakistani mobile number to E.164 format, e.g. "+923001234567".

    Accepts numbers written like "03001234567", "0300-1234567", "+92 300 1234567"
    or "923001234567". Spaces and dashes are ignored. Raise ValueError if the
    result isn't a valid mobile number (+92, then 3, then nine more digits).

    A local number that contains a space is rendered in the pretty
    "+92 XXX XXXXXXX" form; everything else is compact E.164.
    """
    if not isinstance(number, str):
        raise ValueError("phone number must be a string")

    stripped = number.strip()
    if not stripped:
        raise ValueError("phone number is empty")

    is_international = stripped.startswith("+")
    digits = "".join(ch for ch in stripped if ch.isdigit())
    if not digits:
        raise ValueError("phone number contains no digits")

    if is_international:
        full = digits
    elif digits.startswith("0"):
        full = "92" + digits[1:]
    elif digits.startswith("92"):
        full = digits
    else:
        raise ValueError("unrecognized phone number format")

    # Valid Pakistani mobile: 12 digits, "92" country code, then "3", then 9 more.
    if len(full) != 12 or not full.startswith("92") or full[2] != "3":
        raise ValueError("not a valid Pakistani mobile number")

    if " " in stripped and not is_international:
        return "+92 " + full[2:5] + " " + full[5:]
    return "+" + full

