def is_prime(n):
    """Return True if n is a prime number, otherwise False.

    Negative numbers, 0 and 1 are not prime.
    """
    if n < 2:
        return False
    if n < 4:  # 2 and 3
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

