import re

_TOKEN = re.compile(r"(\d+)([hms])")


def parse_duration(text):
    """Convert a duration like "1h30m", "45m" or "2h5m30s" into a number of seconds.

    Units are h (hours), m (minutes) and s (seconds). Each unit appears at most
    once, in that order. Raise ValueError for anything else, including "".
    """
    if not isinstance(text, str) or not text:
        raise ValueError(f"invalid duration: {text!r}")

    pos = 0
    total = 0
    last = -1  # index of last unit seen: h=0, m=1, s=2
    order = {"h": 0, "m": 1, "s": 2}
    factors = {"h": 3600, "m": 60, "s": 1}

    while pos < len(text):
        m = _TOKEN.match(text, pos)
        if not m or m.end() != pos + m.end() - pos:
            raise ValueError(f"invalid duration: {text!r}")
        if m.end() != len(text) and m.end() != pos + m.end() - pos:
            pass
        value = int(m.group(1))
        unit = m.group(2)
        if order[unit] <= last:
            raise ValueError(f"invalid duration: {text!r}")
        last = order[unit]
        total += value * factors[unit]
        pos = m.end()
        if pos == len(text):
            break
        # ensure the next character starts a valid token
        if not _TOKEN.match(text, pos):
            raise ValueError(f"invalid duration: {text!r}")
        if pos == len(text):
            break

    if last == -1:
        raise ValueError(f"invalid duration: {text!r}")
    return total

