    once, in that order. Raise ValueError for anything else, including "".
    """
    if not isinstance(text, str) or not text:
        raise ValueError(f"invalid duration: {text!r}")

    matches = list(_TOKEN.finditer(text))
    # Tokens must cover the whole string with no gaps.
    if not matches or matches[0].start() != 0:
        raise ValueError(f"invalid duration: {text!r}")
    for prev, cur in zip(matches, matches[1:]):
        if cur.start() != prev.end():
            raise ValueError(f"invalid duration: {text!r}")
    if matches[-1].end() != len(text):
        raise ValueError(f"invalid duration: {text!r}")

    total = 0
    last = -1
    for m in matches:
        unit = m.group(2)
        if _ORDER[unit] <= last:  # repeats or out-of-order units
            raise ValueError(f"invalid duration: {text!r}")
        last = _ORDER[unit]
        total += int(m.group(1)) * _FACTORS[unit]
    return total

